// This tab's device keypair: ECDSA P-256, generated by WebCrypto, kept in
// IndexedDB, and never readable by anything - including this file.
//
// Flower authenticates every device by a per-request signature over a canonical
// form (see SignedRequestCanonicalizer). The browser used to be the one head
// that could not take part, because .NET-for-WebAssembly has no asymmetric
// crypto at all, and it stood in a server-minted bearer token instead. This
// module is what removes that exception. The formats line up with the desktop's
// file-backed key exactly, so the server verifies a tab's signature with the
// same code path and no second auth mode:
//
//   curve      P-256                  <-> ECCurve.NamedCurves.nistP256
//   hash       SHA-256                <-> HashAlgorithmName.SHA256
//   public key exportKey("raw")       <-> 0x04 || X(32) || Y(32), DeviceKeyStore
//   signature  raw r||s               <-> DSASignatureFormat.IeeeP1363FixedFieldConcatenation
//
// extractable: false is the point, and it is a *stronger* guarantee than the
// desktop has: the private key is a handle the page may sign with and nobody -
// this module, injected script, a browser extension reading page memory - can
// read out. It is stored as a CryptoKey through IndexedDB's structured clone,
// not as exported bytes, so it never exists in serializable form at all.
//
// Requires a secure context. crypto.subtle is only exposed over HTTPS and on
// localhost, so a tab opened at http://192.168.x.y has no crypto at all and no
// way to be a device. isAvailable() reports that so the app can say so plainly
// rather than failing at the first request - see BrowserSigningKey.

const DB_NAME = "flower";
const DB_VERSION = 1;
const STORE = "identity";
const RECORD_ID = "device-key";

// Cached for the life of the page: opening IndexedDB and importing the record
// on every request would put a database round-trip in front of every signature,
// and there is exactly one identity per tab.
let identity = null;

export function isAvailable() {
    return typeof globalThis.crypto?.subtle?.sign === "function"
        && typeof globalThis.indexedDB !== "undefined";
}

function openDatabase() {
    return new Promise((resolve, reject) => {
        const request = globalThis.indexedDB.open(DB_NAME, DB_VERSION);
        request.onupgradeneeded = () => {
            if (!request.result.objectStoreNames.contains(STORE)) {
                request.result.createObjectStore(STORE);
            }
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
    });
}

function transact(db, mode, action) {
    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE, mode);
        const request = action(tx.objectStore(STORE));
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
    });
}

function toBase64(buffer) {
    const bytes = new Uint8Array(buffer);
    let binary = "";
    // Chunked rather than String.fromCharCode(...bytes): spreading a large
    // array into an argument list overflows the call stack. 65 bytes and 64
    // bytes are what actually pass through here, but the limit is a property of
    // the call, not of today's inputs.
    for (let i = 0; i < bytes.length; i += 0x8000) {
        binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
    }
    return globalThis.btoa(binary);
}

function fromBase64(value) {
    const binary = globalThis.atob(value);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
}

async function load() {
    if (identity) {
        return identity;
    }

    const db = await openDatabase();
    try {
        const stored = await transact(db, "readonly", store => store.get(RECORD_ID));
        if (stored?.privateKey && stored?.publicKeyRaw) {
            identity = stored;
            return identity;
        }

        // First visit in this browser profile. A fresh keypair makes this tab a
        // new, unpaired device - which is exactly what it is. Clearing site data
        // therefore un-pairs the tab and the operator issues another code, the
        // same recovery story as a lost phone.
        const pair = await globalThis.crypto.subtle.generateKey(
            { name: "ECDSA", namedCurve: "P-256" }, false, ["sign", "verify"]);
        const publicKeyRaw = await globalThis.crypto.subtle.exportKey("raw", pair.publicKey);

        const record = { privateKey: pair.privateKey, publicKeyRaw };
        await transact(db, "readwrite", store => store.put(record, RECORD_ID));
        identity = record;
        return identity;
    } finally {
        db.close();
    }
}

// The raw public key, base64 - what the server stores against this device and
// what its fingerprint is derived from.
export async function publicKey() {
    return toBase64((await load()).publicKeyRaw);
}

// Signs the canonical bytes .NET built (base64 in, base64 out), so the string
// being signed is assembled in exactly one place for every head.
export async function sign(payloadBase64) {
    const key = (await load()).privateKey;
    const signature = await globalThis.crypto.subtle.sign(
        { name: "ECDSA", hash: "SHA-256" }, key, fromBase64(payloadBase64));
    return toBase64(signature);
}

// A name for this device in the server's device list. Best-effort and cosmetic:
// the user has to recognize which row is "this browser" when revoking one, and
// "Chrome on macOS" does that where a bare fingerprint does not. Deliberately
// not a fingerprinting exercise - engine name and platform, nothing finer.
export function describe() {
    const agent = globalThis.navigator?.userAgent ?? "";
    const browser =
        /Firefox\//.test(agent) ? "Firefox" :
        /Edg\//.test(agent) ? "Edge" :
        /OPR\//.test(agent) ? "Opera" :
        /Chrome\//.test(agent) ? "Chrome" :
        /Safari\//.test(agent) ? "Safari" : "Browser";
    const platform =
        /Mac OS X/.test(agent) ? "macOS" :
        /Windows/.test(agent) ? "Windows" :
        /Android/.test(agent) ? "Android" :
        /(iPhone|iPad)/.test(agent) ? "iOS" :
        /Linux/.test(agent) ? "Linux" : null;
    return platform ? `${browser} on ${platform}` : browser;
}
